function modifyParallel(source,delta,refresh=true){beginScheduleOverride();let same=runs.filter(r=>r.source===source);if(delta>0&&same.length<4){let base=same[0];runs.push({...base,id:Math.max(...runs.map(r=>r.id))+1,kind:'Parallel run',group:same.length+1})}else if(delta<0&&same.length>1){let remove=same.at(-1);runs=runs.filter(r=>r.id!==remove.id)}same=runs.filter(r=>r.source===source);same.forEach((r,i)=>{r.group=i+1;r.label='Run '+(source+1)+(same.length>1?' · Group '+(i+1):'')});runs.sort((a,b)=>a.time-b.time||a.source-b.source||a.id-b.id);if(refresh)refreshSchedule(true)}
function runGroupControls(t){let same=runs.filter(r=>r.source===t.source);if(same[0]?.id!==t.id)return '';let status=parallelStatus[t.source],label=same.length>=4?'Parallel group limit reached':dirty?'Regenerate to check parallel capacity':status?.possible?'✓ Another complete parallel group possible':status?'Best split found: '+(status.counts||[status.spots]).map(n=>n+'/'+size).join(' + ')+' players':'Regenerate to check parallel capacity';return `<div class="foot"><strong style="color:${status?.possible&&!dirty?'#a8ddbe':'#efd39a'}">${label}</strong><div class="rosteractions" style="margin-top:10px"><button ${same.length>=4?'disabled':''} onclick="modifyParallel(${t.source},1)">Parallelize · + group</button><button ${same.length<=1?'disabled':''} onclick="modifyParallel(${t.source},-1)">Converge · − group</button></div></div>`}
function changeTeamSize(delta){let sizes=[6,12,18,24];size=delta>0?(sizes.find(n=>n>size)||24):([...sizes].reverse().find(n=>n<size)||6);optimize()}
function planningControls(){let runCount=configuredRunCount(),settingsRuns=scheduleOverrideBase||runs,settingsSlots=[...new Set(settingsRuns.map(r=>r.source))].sort((a,b)=>a-b);return `<aside class="panel comp-settings"><h2>Run settings</h2>${lockPriorityControls()}<label class="field compactfield"><span>Preset</span><select onchange="preset(this.value)"><option>Custom / current</option><option>Balanced</option><option>Progression</option></select></label><div class="settingrows"><div class="settingrow"><span>Players / team</span><div class="stepper"><button type="button" aria-label="Fewer players" ${size<=6?'disabled':''} onclick="changeTeamSize(-1)">−</button><strong>${size}</strong><button type="button" aria-label="More players" ${size>=24?'disabled':''} onclick="changeTeamSize(1)">+</button></div></div><div class="settingrow"><span>Hours per run</span><div class="stepper"><button type="button" aria-label="Shorter run duration" ${duration<=.25?'disabled':''} onclick="nudgeDuration(-1)">−</button><strong>${formatDuration(duration)}</strong><button type="button" aria-label="Longer run duration" ${duration>=6?'disabled':''} onclick="nudgeDuration(1)">+</button></div></div><div class="settingrow"><span>Runs</span><div class="stepper"><button type="button" aria-label="Remove last run" ${runCount<=1?'disabled':''} onclick="changeRunCount(-1)">−</button><strong>${runCount}</strong><button type="button" aria-label="Add run" ${runCount>=16?'disabled':''} onclick="changeRunCount(1)">+</button></div></div></div><label class="field compactfield"><span>Suggest schedule</span><select onchange="suggestSchedule=this.value==='on';optimize()"><option value="off" ${!suggestSchedule?'selected':''}>Off</option><option value="on" ${suggestSchedule?'selected':''}>On</option></select><small>Only removes sequential slots or adds parallel groups, up to the configured ${recommendationRunLimit??runCount} run limit. Accepted shorter schedules retain that limit for future comparisons.</small></label><button class="primary" style="width:100%;margin-top:12px" onclick="commitRoster()">Commit & generate teams</button><div class="runtimes"><div class="templatelibraryhead"><strong>Run times</strong><span class="muted">Pacific</span></div>${settingsSlots.map((source,i)=>{let r=settingsRuns.find(x=>x.source===source);return `<div class="runtimerow"><span>${i?esc(r.label):'Start · '+esc(r.label)}</span><input type="time" value="${time(r.time)}" ${i?'disabled title="Derived from start time and hours per run"':'onchange="changeTime('+r.id+',this.value)"'}></div>`}).join('')}</div></aside>`}
function playerRunSummary(){let rows=new Map(players.map(p=>[p.id,{id:p.id,name:p.name,preferences:p.preferredClasses||[],assignments:[]} ]));for(let t of teams)for(let member of t.members){if(!rows.has(member.id))rows.set(member.id,{id:member.id,name:member.name,preferences:member.preferredClasses||[],assignments:[]});rows.get(member.id).assignments.push(member)}return [...rows.values()].map(row=>{let roles={};for(let m of row.assignments)roles[m.role]=(roles[m.role]||0)+1;return {...row,runs:row.assignments.length,firstChoices:row.preferences.length?row.assignments.filter(m=>row.preferences.includes(m.c)).length:null,roles}}).sort((a,b)=>a.name.localeCompare(b.name))}
function summaryAssignmentIcons(player){let choices=new Map();for(let m of player.assignments){let key=m.c+'|'+m.spec;let entry=choices.get(key);if(entry)entry.count++;else choices.set(key,{...m,count:1})}return [...choices.values()].map(c=>`<span class="summaryassignment" title="${esc(c.spec+' '+c.c+' · '+c.count+' run'+(c.count===1?'':'s'))}">${icon(c)}<span class="summaryiconcount">×${c.count}</span>${player.preferences.includes(c.c)?'<span class="summarypreferred" aria-label="First-choice class">★</span>':''}${experienceBadge(c)}</span>`).join('')||'<span class="muted">—</span>'}
function playerSummaryCard(){return `<section class="panel tablewrap playersummary" style="margin-top:20px"><h2>Player run summary</h2><p class="muted">Colored icons show assigned class/specs; × counts show runs. ★ marks a starred first-choice class. Exp / Inexp badges reflect class experience markers.${dirty?' Pending edits: regenerate teams to apply roster changes.':''}</p><table><thead><tr><th>Player</th><th>Runs</th><th>Assigned classes / specs</th><th>Roles played</th></tr></thead><tbody>${playerRunSummary().map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td><span class="summaryruns ${p.runs?'':'empty'}">${p.runs}</span></td><td><div class="summaryicons">${summaryAssignmentIcons(p)}</div></td><td><div class="summaryroles">${Object.entries(p.roles).map(([role,count])=>`<span class="role ${esc(role)}">${esc(role)} × ${count}</span>`).join('')||'<span class="muted">—</span>'}</div></td></tr>`).join('')}</tbody></table></section>`}

function assignmentNotes(member,raid,schedule=teams){
 let notes=[],player=players.find(p=>p.id===member.id)||member;
 let appearances=schedule.reduce((n,t)=>n+t.members.filter(m=>characterKey(m)===characterKey(member)).length,0);
 if(appearances>1)notes.push('Soft locked · '+member.c+' assigned in '+appearances+' runs. Repeat fallback was allowed by the selected repeat-character policy.');
 let copies=raid.members.filter(m=>m.c===member.c).length;
 if(copies>1)notes.push('Duplicate class · '+copies+' '+member.c+'s in this raid. Class variety is a soft preference.');
 if(isTentativeForRun(player,raid))notes.push('Tentative signup · included in normal selection; a confirmed substitute is checked below.');
 if(player.deprioritizedClasses?.includes(member.c))notes.push('Deprioritized class · remains eligible for required comp and coverage.');

 if(rolePriorities[member.role]?.[member.c+'|'+member.spec]===2)notes.push('Deprioritized for '+member.role.toLowerCase()+' · role priority is a soft preference.');
 let preferred=template[member.role]?.[1],count=raid.members.filter(m=>m.role===member.role).length;
 if(preferred!==undefined&&member.role!=='DPS'&&count>preferred)notes.push('Over role cap · '+count+' '+member.role.toLowerCase()+'s assigned, max '+preferred+'.');
 return notes;
}
function tentativeRosterBadge(p){let slots=runSlots().filter(source=>isTentativeForRun(p,{source}));if(!slots.length)return '';return `<small class="tentativebadge">Tentative${slots.length===runSlots().length?'':' · runs '+slots.map(i=>i+1).join(', ')}</small>`}
function rosterPlayerFor(p){return p&&players.find(x=>x.id===p.id)||p}
function isRaidLeader(p){return !!(rosterPlayerFor(p)?.raidLeader||p?.raidLeader)}
function isPrimary(p){let r=rosterPlayerFor(p);return !!(r?.primary??r?.kinsman??p?.primary??p?.kinsman)}
function isKinsman(p){return isPrimary(p)}
function migratePrimary(p){if(p.primary===undefined&&p.kinsman!==undefined)p.primary=!!p.kinsman;delete p.kinsman;return p}
function raidLeaderRequired(){return (players||[]).some(p=>p.raidLeader)}
function raidLeaderDeficit(members){return raidLeaderRequired()&&!(members||[]).some(isRaidLeader)?1:0}
function rolesWithinHardCaps(members){return Object.keys(template).every(role=>{if(role==='DPS')return true;return (members||[]).filter(p=>p.role===role).length<=roleHardMax(role)})}
function ensureRaidLeaderSeat(members,available,run,used,characters){
 if(!raidLeaderDeficit(members))return members;
 let occupied=new Set(members.map(p=>p.id));
 let leaders=available.filter(p=>isRaidLeader(p)&&!occupied.has(p.id)).flatMap(p=>choicesFor(p,run).map((c,rank)=>{let key=characterKey({id:p.id,charId:c.charId,c:c.c});if(forbidsInexperiencedLock(p,c.c,characters[key]))return null;return {...p,...c,rank,repeated:!!characters[key]}}).filter(Boolean));
 if(!leaders.length)return members;
 let best=null,bestScore=null;
 for(let i=0;i<members.length;i++){
  let role=members[i].role,min=role==='DPS'?0:Number(template[role]?.[0])||0;
  let others=members.filter((_,j)=>j!==i);if(others.filter(p=>p.role===role).length<min)continue;
  for(let leader of leaders){
   let next=members.slice();next[i]=leader;
   if(!rolesWithinHardCaps(next))continue;
   let score=assignmentScore(next,used,characters);
   if(bestScore===null||score<bestScore){bestScore=score;best=next}
  }
 }
 return best||members;
}
function toggleRaidLeader(id){let p=players.find(x=>x.id===id);if(!p)return;if(typeof rememberRosterEdit==='function')rememberRosterEdit('raid leader');if(p.raidLeader)delete p.raidLeader;else p.raidLeader=true;if(typeof fellowshipSearchCache!=='undefined')fellowshipSearchCache.clear();optimize()}
function togglePrimary(id){let p=players.find(x=>x.id===id);if(!p)return;if(typeof rememberRosterEdit==='function')rememberRosterEdit('primary');migratePrimary(p);if(p.primary)delete p.primary;else p.primary=true;fellowshipSearchCache.clear();optimize()}
function toggleKinsman(id){togglePrimary(id)}
function isRosterTentative(p){let slots=runSlots();return !!slots.length&&slots.every(source=>isTentativeForRun(p,{source}))}
function ensureTentativeRuns(p){let len=Math.max(p.available?.length||0,Math.max(0,...runSlots())+1,recommendationRunLimit||0,1);p.tentativeRuns??=Array(len).fill(false);while(p.tentativeRuns.length<len)p.tentativeRuns.push(!!p.tentativeRuns.at(-1));p.tentativeRuns=p.tentativeRuns.slice(0,Math.max(len,p.tentativeRuns.length));return p}
function toggleRosterTentative(id){let p=players.find(x=>x.id===id);if(!p)return;if(typeof rememberRosterEdit==='function')rememberRosterEdit('tentative');ensureTentativeRuns(p);let next=!isRosterTentative(p);for(let source of runSlots())p.tentativeRuns[source]=next;if(!p.tentativeRuns.some(Boolean))delete p.tentativeRuns;if(typeof fellowshipSearchCache!=='undefined')fellowshipSearchCache.clear();optimize()}
function rosterFlagIcon(kind){if(kind==='leader')return '<svg class="rosterflagsvg" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7.5 7.5 11 12 4l4.5 7L21 7.5V19H3V7.5Zm2.2 9.3h13.6v-5.4l-2.7 2-4.1-6.3-4.1 6.3-2.7-2v5.4Z"/></svg>';if(kind==='primary')return '<svg class="rosterflagsvg" viewBox="0 0 24 24" aria-hidden="true"><path d="M9.2 16.6 4.8 12.2l1.4-1.4 3 3 8-8 1.4 1.4-9.4 9.4Z"/></svg>';return '<span class="rostershrug" aria-hidden="true">¯\\_(ツ)_/¯</span>'}
function rosterFlagButton(p,kind,selected,action,label){return `<button type="button" class="rosterflag ${kind}${selected?' selected':''}" aria-label="${esc(p.name)}: ${label}" aria-pressed="${!!selected}" title="${label}" onclick="${action}('${p.id}')">${rosterFlagIcon(kind)}</button>`}
function rosterFlagIcons(p){return `<div class="rosterflags" role="group" aria-label="${esc(p.name)} roster flags">${rosterFlagButton(p,'leader',!!p.raidLeader,'toggleRaidLeader','Raid leader')}${rosterFlagButton(p,'primary',isPrimary(p),'togglePrimary','Primary')}${rosterFlagButton(p,'tentative',isRosterTentative(p),'toggleRosterTentative','Tentative')}</div>`}
function playerSignupClasses(p){ensurePlayerCharacters(p);let names=(p.signupCharacters||[]).map(s=>s.c);if(!names.length&&Array.isArray(p.signupClasses))names=p.signupClasses.slice();if(!names.length&&Array.isArray(p.choices))names=p.choices.map(c=>c.c);return [...new Set(names.filter(c=>classes[c]))]}
function experienceState(p,className){let roster=rosterPlayerFor(p);if(!roster||!className)return 'default';if(roster.inexperiencedClasses?.includes(className))return 'inexperienced';if(roster.experiencedClasses?.includes(className))return 'experienced';return 'default'}
function experienceBadge(member){let state=experienceState(member,member?.c);return state==='experienced'?'<small class="expbadge exp">Exp</small>':state==='inexperienced'?'<small class="expbadge inexp">Inexp</small>':''}
function raidLeaderBadge(member){return isRaidLeader(member)?'<small class="raidleaderbadge">Raid leader</small>':''}
function kinsmanBadge(member){return isKinsman(member)?'<small class="kinsmanbadge">Primary</small>':''}
function cleanExperienceLists(p){if(!p)return;let valid=new Set(playerSignupClasses(p));if(p.experiencedClasses){p.experiencedClasses=p.experiencedClasses.filter(c=>valid.has(c)&&!p.inexperiencedClasses?.includes(c));if(!p.experiencedClasses.length)delete p.experiencedClasses}if(p.inexperiencedClasses){p.inexperiencedClasses=p.inexperiencedClasses.filter(c=>valid.has(c)&&!p.experiencedClasses?.includes(c));if(!p.inexperiencedClasses.length)delete p.inexperiencedClasses}delete p.isNewPlayer}
function migratePlayerExperience(p){if(!p)return p;let hasExp=(p.experiencedClasses?.length||0)+(p.inexperiencedClasses?.length||0)>0;if(p.isNewPlayer===true&&!hasExp){p.inexperiencedClasses=playerSignupClasses(p);if(!p.inexperiencedClasses.length)delete p.inexperiencedClasses}cleanExperienceLists(p);return p}
function cycleClassExperience(id,name){let p=players.find(x=>x.id===id);if(!p||!classes[name])return;if(typeof rememberRosterEdit==='function')rememberRosterEdit('class experience');p.experiencedClasses??=[];p.inexperiencedClasses??=[];if(p.experiencedClasses.includes(name)){p.experiencedClasses=p.experiencedClasses.filter(c=>c!==name);p.inexperiencedClasses.push(name)}else if(p.inexperiencedClasses.includes(name)){p.inexperiencedClasses=p.inexperiencedClasses.filter(c=>c!==name)}else{p.experiencedClasses.push(name);p.inexperiencedClasses=p.inexperiencedClasses.filter(c=>c!==name)}cleanExperienceLists(p);if(typeof fellowshipSearchCache!=='undefined')fellowshipSearchCache.clear();optimize()}
function experienceStarButton(p,name){let state=experienceState(p,name),star=state==='experienced'?'full':state==='inexperienced'?'empty':'half',label=state==='experienced'?'experienced':state==='inexperienced'?'inexperienced':'default';return `<button type="button" class="classexp ${state!=='default'?'selected':''}" aria-label="${esc(p.name)}: ${esc(name)} experience ${label}; click to cycle" aria-pressed="${state!=='default'}" title="Exp · ${label} · click to cycle" onclick="cycleClassExperience('${p.id}','${name}')"><span class="explabel">Exp</span>${priorityStar(star)}</button>`}
function teamClassIcon(p){return icon(p).replace('class="classicon ',`class="classicon ${isCharacterSoftLocked(p.id,p.charId||p.c,p.c)?'softlocked ':''}`)}
function buildTentativeAlternatives(schedule,budgetMs=1000){
 let deadline=Date.now()+budgetMs,baseline=null;
 for(let raid of schedule){raid.alternatives={};for(let member of raid.members){let person=players.find(p=>p.id===member.id)||member;if(!isTentativeForRun(person,raid))continue;
  if(Date.now()>deadline){raid.alternatives[member.id]={status:'limited',choices:[]};continue}
  baseline??=scheduleHardDeficit(schedule);
  let occupied=new Set(raid.members.map(p=>p.id));
  let eligibilityContext=schedule.map(t=>t.id===raid.id?{...t,members:t.members.filter(m=>m.id!==member.id)}:t);
  let pool=players.filter(p=>!occupied.has(p.id)&&availableForRun(p,raid)&&!isTentativeForRun(p,raid)&&!schedule.some(t=>t.id!==raid.id&&Math.abs(t.time-raid.time)+1e-8<duration&&t.members.some(m=>m.id===p.id))).flatMap(p=>choicesFor(p,raid).map(c=>({...p,...c,repeated:eligibilityContext.some(t=>t.members.some(m=>characterKey(m)===characterKey({...p,...c})))})));
  pool.sort((a,b)=>(a.role!==member.role)-(b.role!==member.role)||allocationDraftTier(a,eligibilityContext)-allocationDraftTier(b,eligibilityContext)||(a.c!==member.c)-(b.c!==member.c)||playerPreferenceCost(a,a.c)-playerPreferenceCost(b,b.c));
  let chosen=[],checked=0;for(let candidate of pool.slice(0,12)){if(Date.now()>deadline||chosen.length>=2)break;checked++;let replaced=schedule.map(t=>t.id===raid.id?{...t,members:t.members.map(m=>m.id===member.id?candidate:m)}:t);if(!scheduleFeasible(replaced)||hasInexperiencedSoftLock(replaced)||!queryEligibility({run:raid,schedule:schedule.map(t=>t.id===raid.id?{...t,members:t.members.filter(m=>m.id!==member.id)}:t),allowLocks:true,playerId:candidate.id}).members.some(c=>characterKey(c)===characterKey(candidate)&&c.spec===candidate.spec))continue;let objective=scheduleHardDeficit(replaced);if(objective>baseline+1e-8)continue;let repeated=schedule.some(t=>t.id!==raid.id&&t.members.some(m=>characterKey(m)===characterKey(candidate)));if(!chosen.some(c=>c.id===candidate.id))chosen.push({id:candidate.id,name:candidate.name,c:candidate.c,spec:candidate.spec,role:candidate.role,charId:candidate.charId,repeated})}
  raid.alternatives[member.id]={status:chosen.length?'found':checked<pool.length?'limited':'none',choices:chosen};
 }}return schedule;
}
function tentativeAlternativeHTML(member,raid){let person=players.find(p=>p.id===member.id)||member;if(!isTentativeForRun(person,raid))return '';let result=raid.alternatives?.[member.id];return `<div class="alternativenote"><strong>If unavailable:</strong> ${result?.choices?.length?result.choices.map(c=>`${icon(c)} <span>${esc(c.name)} · ${esc(c.spec+' '+c.c)}${c.repeated?' · repeat fallback':''}</span>`).join(' <span>or</span> '):result?.status==='none'?'No confirmed eligible substitute found.':result?.status==='limited'?'No substitute found within the check limit.':'Substitute check pending.'}<small>Each suggestion is checked independently against the current schedule; regenerate after roster changes.</small></div>`}
function assignmentNotesHTML(member,raid){let notes=assignmentNotes(member,raid);return notes.length?`<ul class="assignmentnotes">${notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul>`:''}
function teamArtifactNotesHTML(raid){let notes=[];if(raid.members.length<size)notes.push((size-raid.members.length)+' empty spot(s) · no complete eligible layout found in this search.');for(let r of raid.shortages||[])notes.push('Missing '+r.count+' '+r.role.toLowerCase()+' · closest available comp shown.');let failed=(raid.constraintResults||[]).filter(r=>r.strength==='hard'&&!r.pass);for(let r of failed)notes.push('Unmet '+r.name+(r.group?' · F'+r.group:'')+' · '+r.detail);return notes.length?`<div class="artifactnotes"><strong>Comp notes</strong><ul>${notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul><small>The search is bounded; this result does not prove a better layout is impossible.</small></div>`:''}
function teamView(){if(!hasGenerated)return `${teamScheduleControls()}<section class="panel"><h2>Generate teams</h2><p class="muted">Select specs and availability in Roster, set the template in Comp, then commit to build teams.</p><button class="primary" onclick="commitRoster()">Commit roster & generate teams</button></section>`;let missed=uncovered(teams),spots=teams.reduce((n,t)=>n+t.members.length,0);return `<div><section>${teamScheduleControls()}${recommendedConfigurationHTML()}<div class="stats"><div class="stat"><strong>${players.length}</strong><small>Unique players</small></div><div class="stat"><strong>${players.length-missed.length}/${players.length}</strong><small>Have a run</small></div><div class="stat"><strong>${teams.filter(t=>t.valid).length}/${runs.length}</strong><small>Complete teams</small></div><div class="stat"><strong>${spots}</strong><small>Assigned spots</small></div><div class="stat"><strong>${lockedPlayerCount(teams)}</strong><small>Locked run assignments</small></div></div><div class="toolbar"><div><h2 style="margin:0">Raid night</h2><small>Committed roster · availability editable in Roster</small></div><div class="rosteractions"><button class="primary" onclick="commitRoster()">Regenerate teams</button><button onclick="openDiscordExport(true)">Copy all runs</button><button onclick="exportTeamsPng()">Export PNG</button><button onclick="exportPlan()">Download teams</button></div></div>${dirty?`<div class="notice">Roster or comp changes are pending. <button class="primary" onclick="commitRoster()">Commit & regenerate</button></div>`:''}${message?`<div class="notice">${esc(message)}</div>`:''}${players.some(p=>!p.choices.some(c=>!c.flexible))?`<div class="notice">${players.filter(p=>!p.choices.some(c=>!c.flexible)).length} players need spec selections. <button onclick="setTab('Roster')">Select specs</button></div>`:''}${constraintChecksHTML(evaluateScheduleRules(teams).filter(r=>r.raidId===null))}<div class="teams">${teams.map(t=>`<article class="team"><div class="teamhead"><div><h3>${esc(t.label)}</h3><small>${time(t.time)} Pacific</small></div><div><span class="badge" style="background:${t.valid?'#243e33':'#443522'};color:${t.valid?'#a8ddbe':'#efd39a'}">${t.valid?'Ready':t.members.length<size?'Needs players':'Adjust comp'} · ${t.members.length}/${size}</span></div></div>${runGroupControls(t)}${teamArtifactNotesHTML(t)}${t.members.map(p=>`<div class="rosterrow">${teamClassIcon(p)}<div><strong>${esc(p.name)}</strong>${raidLeaderBadge(p)}${kinsmanBadge(p)}${experienceBadge(p)}${assignmentNotesHTML(p,t)}${tentativeAlternativeHTML(p,t)}</div><span class="role ${p.role}">${p.role}</span></div>`).join('')}${Object.entries(template).flatMap(([r,v])=>Array(Math.max(0,v[0]-t.members.filter(m=>m.role===r).length)).fill(r)).map(r=>`<div class="rosterrow"><span class="avatar">?</span><button class="shortagelink" onclick="openRoleShortage(${t.id},'${r}')">Open ${r.toLowerCase()} spot · find players</button><span class="role ${r}">${r}</span></div>`).join('')}<div class="foot">${t.repeatCount?t.repeatCount+' same-player/class repeat(s) needed.':'No repeated player/class assignments.'}${t.shortages?.length?'<br>Missing: '+t.shortages.map(r=>shortageLink(t,r)).join(' '):''}${t.preferredShortages?.length?'<br>Below preferred: '+t.preferredShortages.map(r=>r.count+' '+r.role.toLowerCase()).join(', '):''}${t.members.length<size?'<br>'+(size-t.members.length)+' empty spot(s).':''}${t.classDuplicates?'<br>'+t.classDuplicates+' duplicate-class spot(s).':''}</div>${constraintChecksHTML(t.constraintResults)}${fellowshipRosterHTML(t)}</article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>${!players.length?'No signups loaded':missed.length?'Still need a first run':'Everyone has a run'}</h3><p class="muted">${!players.length?'Import an event link or saved session to start planning.':missed.length?missed.map(p=>esc(p.name)).join(' · '):'All unique players have at least one assignment.'}</p>${missed.length&&!recommendations.length?'<small>No complete additional team found within the current availability and template.</small>':''}</div>${playerSummaryCard()}</section></div>`}
function icon(c){return `<span class="classicon ${c.spec.toLowerCase()}" title="${esc(c.spec+' '+c.c)}"><img src="icons/${c.c.toLowerCase()}.png" alt="${esc(c.spec+' '+c.c)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span hidden>${esc(c.c.slice(0,2))}</span></span>`}
function removeSignupClass(id,name){let p=players.find(p=>p.id===id);if(!p)return;ensurePlayerCharacters(p);for(let slot of p.signupCharacters.filter(s=>s.c===name))removeSignupCharacter(id,slot.id,false);if(p.preferredClasses)p.preferredClasses=p.preferredClasses.filter(c=>c!==name);if(p.deprioritizedClasses)p.deprioritizedClasses=p.deprioritizedClasses.filter(c=>c!==name);if(p.experiencedClasses)p.experiencedClasses=p.experiencedClasses.filter(c=>c!==name);if(p.inexperiencedClasses)p.inexperiencedClasses=p.inexperiencedClasses.filter(c=>c!==name);cleanExperienceLists(p);delete p.eventChoices;addingClassFor=null;optimize()}
function removeSignupCharacter(id,charId,refresh=true){let p=players.find(p=>p.id===id);if(!p)return;ensurePlayerCharacters(p);let slot=p.signupCharacters.find(s=>s.id===charId);if(!slot)return;p.signupCharacters=p.signupCharacters.filter(s=>s.id!==charId);p.choices=p.choices.filter(c=>c.charId!==charId);if(!p.signupCharacters.some(s=>s.c===slot.c)){if(p.preferredClasses)p.preferredClasses=p.preferredClasses.filter(c=>c!==slot.c);if(p.deprioritizedClasses)p.deprioritizedClasses=p.deprioritizedClasses.filter(c=>c!==slot.c);if(p.experiencedClasses)p.experiencedClasses=p.experiencedClasses.filter(c=>c!==slot.c);if(p.inexperiencedClasses)p.inexperiencedClasses=p.inexperiencedClasses.filter(c=>c!==slot.c)}p.signupClasses=p.signupCharacters.map(s=>s.c);cleanExperienceLists(p);delete p.eventChoices;addingClassFor=null;if(refresh)optimize()}
function addSignupClass(id,name){let p=players.find(p=>p.id===id);if(!p||!classes[name])return;ensurePlayerCharacters(p);let charId=newCharId();p.signupCharacters.push({id:charId,c:name});for(let o of opts.filter(o=>o.c===name))p.choices.push({...o,charId,flexible:true});p.signupClasses=p.signupCharacters.map(s=>s.c);addingClassFor=null;optimize()}
function toggleAddClass(id){addingClassFor=addingClassFor===id?null:id;render()}
function signupClassNames(p){return signupSlots(p).map(s=>s.c)}
function quickSpec(id,n,charId){let p=players.find(p=>p.id===id);if(!p)return;ensurePlayerCharacters(p);if(!charId){let c=opts[n];charId=p.choices.find(o=>o.c===c.c)?.charId||p.signupCharacters.find(s=>s.c===c.c)?.id;if(!charId){addSignupClass(id,c.c);p=players.find(x=>x.id===id);charId=p.signupCharacters.filter(s=>s.c===c.c).at(-1)?.id}}let c=opts[n],i=p.choices.findIndex(o=>o.charId===charId&&o.spec===c.spec&&!o.flexible);if(i>=0)p.choices.splice(i,1);else{p.choices=p.choices.filter(o=>!(o.charId===charId&&o.spec===c.spec));p.choices.push({...c,charId});}optimize()}
function toggleRunAvailability(id,n){let p=players.find(p=>p.id===id);if(typeof rememberRosterEdit==='function')rememberRosterEdit('availability change');p.available[n-1]=!p.available[n-1];optimize()}
function runAvailabilityPicker(p){let numbers=runSlots().map(i=>i+1);while(p.available.length<Math.max(...numbers))p.available.push(!!p.available.at(-1));return `<div class="runpicks" role="group" aria-label="${esc(p.name)} run availability">${numbers.map(n=>`<button class="runpick ${p.available[n-1]?'available':''}" aria-label="${esc(p.name)} available for run ${n}" aria-pressed="${!!p.available[n-1]}" title="Run ${n}" onclick="toggleRunAvailability('${p.id}',${n})">${n}</button>`).join('')}</div>`}

function priorityStar(state){return `<span class="prioritystar ${state}" aria-hidden="true">☆<span>★</span></span>`}
