function cyclePlayerPreference(id,name){let p=players.find(p=>p.id===id);if(!p)return;p.deprioritizedClasses??=[];if(p.preferredClasses?.includes(name)){p.preferredClasses=p.preferredClasses.filter(c=>c!==name);p.deprioritizedClasses.push(name)}else if(p.deprioritizedClasses.includes(name)){p.deprioritizedClasses=p.deprioritizedClasses.filter(c=>c!==name)}else{p.preferredClasses??=[];p.preferredClasses.push(name)}optimize()}
