function quickSpecPicker(p){let slots=signupSlots(p),counts={};for(let s of slots)counts[s.c]=(counts[s.c]||0)+1;let seen={};let cards=slots.map(slot=>{let name=slot.c;seen[name]=(seen[name]||0)+1;let label=counts[name]>1?name+' · '+seen[name]:name;return `<div class="quickclass"><div class="classlabel"><span>${esc(label)}</span><div class="classactions"><button type="button" class="playerpriority ${p.preferredClasses?.includes(name)?'selected':''}" aria-label="${esc(p.name)}: ${esc(name)} ${p.preferredClasses?.includes(name)?'prioritized':p.deprioritizedClasses?.includes(name)?'deprioritized':'neutral'}; click to cycle" aria-pressed="${!!p.preferredClasses?.includes(name)}" title="${esc(name)} · ${p.preferredClasses?.includes(name)?'Prioritized':p.deprioritizedClasses?.includes(name)?'Deprioritized':'Neutral'} · click to cycle" onclick="cyclePlayerPreference('${p.id}','${name}')">${priorityStar(p.preferredClasses?.includes(name)?'full':p.deprioritizedClasses?.includes(name)?'empty':'half')}</button>${experienceStarButton(p,name)}<button type="button" class="removeclass" aria-label="Remove ${esc(label)}" onclick="removeSignupCharacter('${p.id}','${slot.id}')">×</button></div></div><div class="quickicons">${(classes[name]||[]).map(([spec,role])=>{let n=opts.findIndex(o=>o.c===name&&o.spec===spec);let selected=p.choices.some(o=>o.charId===slot.id&&o.spec===spec&&!o.flexible),locked=isCharacterSoftLocked(p.id,slot.id,name)&&teams.some(t=>t.members.some(m=>m.id===p.id&&(m.charId?m.charId===slot.id:m.c===name)&&m.spec===spec));return `<button class="spec-toggle ${selected?'chosen':''} ${locked?'softlocked':''}" aria-label="${esc(p.name)}: ${spec} ${label}" aria-pressed="${selected}" title="${spec} ${label}${locked?' · Soft locked: this character is assigned to multiple runs':''} · ${selected?'selected':'click to enable'}" onclick="quickSpec('${p.id}',${n},'${slot.id}')">${icon(opts[n])}<span class="selectionmark">${selected?'✓':'+'}</span></button>`}).join('')}</div></div>`}).join('');let addCard=addingClassFor===p.id?`<div class="quickclass addclass expanded"><div class="classlabel"><span>Add class</span><button type="button" class="removeclass" aria-label="Cancel add class" onclick="addingClassFor=null;render()">×</button></div><div class="addclasslist">${Object.keys(classes).map(name=>`<button type="button" class="addclassoption" onclick="addSignupClass('${p.id}','${name}')">${esc(name)}${counts[name]?' · add another':''}</button>`).join('')}</div></div>`:`<div class="quickclass addclass"><button type="button" class="addclassbtn" aria-label="Add class for ${esc(p.name)}" onclick="toggleAddClass('${p.id}')">+</button></div>`;return `<div class="quickclasses">${cards}${addCard}</div>${slots.some(slot=>isCharacterSoftLocked(p.id,slot.id,slot.c))?'<small class="locklegend">Silver icon border: character assigned to multiple runs'+(dirty?' in the last generated plan':'')+'.</small>':''}<small>${p.choices.filter(c=>!c.flexible).length?'':'Select at least one spec to assign this player.'}</small>`}
function addPlayerForm(){if(!addPlayerOpen)return '';return `<form class="panel addplayerform" style="margin-bottom:20px" onsubmit="addManualPlayer(event)"><h3>Add player</h3><div class="addfields"><label class="field"><span>Player name</span><input id="newplayername" required maxlength="100" placeholder="Display name"></label><label class="field"><span>Discord user ID (optional)</span><input id="newplayerid" inputmode="numeric" pattern="[0-9]{17,20}" placeholder="Use the ID to match Discord signups"></label><label class="field"><span>First class</span><select id="newplayerclass">${Object.keys(classes).map(c=>`<option>${c}</option>`).join('')}</select></label></div><p class="muted">After adding, select specs, availability and any other classes in the roster.</p><div class="rosteractions"><button type="submit" class="primary">Add to roster</button><button type="button" onclick="addPlayerOpen=false;render()">Cancel</button></div><p id="addplayererror" role="alert"></p></form>`}
function addManualPlayer(event){event.preventDefault();let name=document.getElementById('newplayername').value.trim(),discordId=document.getElementById('newplayerid').value.trim(),c=document.getElementById('newplayerclass').value;let error=document.getElementById('addplayererror');if(!name){error.textContent='Enter a player name.';return}if(discordId&&!/^\d{17,20}$/.test(discordId)){error.textContent='Discord IDs must contain 17–20 digits.';return}if(discordId&&players.some(p=>p.id===discordId)){error.textContent='That Discord user is already in the roster. Edit their existing row.';return}if(!classes[c]){error.textContent='Select a valid class.';return}let id=discordId||'manual-'+Date.now()+'-'+Math.random().toString(36).slice(2,9),charId=newCharId();players.push({id,name,choices:opts.filter(o=>o.c===c).map(o=>({...o,charId,flexible:true})),signupClasses:[c],signupCharacters:[{id:charId,c}],available:Array(runSlots().length).fill(false),max:runSlots().length,manual:true});addPlayerOpen=false;addingClassFor=null;tab='Roster';optimize();toast(name+' added. Select specs and availability.')}
function removePlayer(id){let index=players.findIndex(p=>p.id===id);if(index<0)return;if(typeof rememberRosterEdit==='function')rememberRosterEdit('player removal');removedPlayer={player:players[index],index};players.splice(index,1);if(addingClassFor===id)addingClassFor=null;optimize();toast(removedPlayer.player.name+' removed. Undo is available in Roster.')}
function undoRemovePlayer(){if(!removedPlayer)return;if(typeof undoRosterEdit==='function'){undoRosterEdit();return}if(players.some(p=>p.id===removedPlayer.player.id)){toast('This player is already in the roster');return}players.splice(Math.min(removedPlayer.index,players.length),0,removedPlayer.player);removedPlayer=null;optimize();toast('Player restored')}
let shortageFilter=null;
function openRoleShortage(runId,role){let run=runs.find(r=>r.id===runId);if(!run)return;shortageFilter={runId,role};tab='Roster';render()}
function shortagePlayers(){if(!shortageFilter)return players;let run=runs.find(r=>r.id===shortageFilter.runId);if(!run){shortageFilter=null;return players}return players.filter(p=>availableForRun(p,run)&&!teams.some(t=>t.id!==run.id&&Math.abs(t.time-run.time)+1e-8<duration&&t.members.some(m=>m.id===p.id))&&(shortageFilter.role==='Raid leader'?isRaidLeader(p):p.choices.some(c=>c.role===shortageFilter.role&&(!p.eventChoices?.[run.source]?.length||p.eventChoices[run.source].some(e=>e.c===c.c&&(e.flexible||e.spec===c.spec))))))}
function shortageFilterMarkup(){if(!shortageFilter)return '';let run=runs.find(r=>r.id===shortageFilter.runId);if(!run)return '';let count=shortagePlayers().length;let leader=shortageFilter.role==='Raid leader';return `<div class="notice"><strong>${esc(shortageFilter.role)} candidates · ${esc(run.label)} · ${count} player(s)</strong><p>${leader?'Players marked as raid leaders who are available for this run. Mark leaders in Roster, then regenerate.':'Available players with a matching class/spec, including specs not yet enabled. Players already in another overlapping group are excluded. Select playable specs, then regenerate to apply.'}</p><button onclick="shortageFilter=null;render()">Show full roster</button></div>`}
function shortageLink(t,r){return `<button class="shortagelink" onclick="openRoleShortage(${t.id},'${r.role}')">Missing ${r.count} ${r.role.toLowerCase()} · find players</button>`}
function signupView(){return `<div class="toolbar"><div><h2>Roster</h2><p class="muted">Click the colored icons for specs each player can play. Select multiple specs if needed. Select run availability under each name. Use the crown, check and shrug icons under each name for Raid leader, Primary and Tentative. Raid leaders are required on every generated team when any are marked. Primary gets first-run priority and additional unlocked runs before other players receive extras. Everyone’s first run takes precedence over additional runs. Tentative marks an unconfirmed signup for every configured run; confirmed substitutes are still searched for assigned tentatives. Preference stars cycle neutral (half), prioritized (full) and deprioritized (empty). Exp stars cycle default (half), experienced (full) and inexperienced (empty) per class. Use × to remove a character or + to add another class, including a second copy of the same class for alts. Duplicate classes are separate characters for locks.</p></div><div class="rostered"><button class="primary" onclick="addPlayerOpen=!addPlayerOpen;render()">Add player</button><button onclick="setTab('Comp')">Review comp</button><button class="primary" onclick="commitRoster()">Commit roster & generate teams</button></div></div>${addPlayerForm()}${shortageFilterMarkup()}${typeof rosterUndo!=='undefined'&&rosterUndo.length?`<div class="notice"><button onclick="undoRosterEdit()">Undo ${esc(rosterUndo.at(-1).label)}</button></div>`:''}${removedPlayer&&typeof rosterUndo==='undefined'?`<div class="notice recommend"><span>${esc(removedPlayer.player.name)} removed from the roster.</span><button onclick="undoRemovePlayer()">Undo remove</button></div>`:''}<p class="muted">${runs.map(r=>esc(r.label)+' · '+time(r.time)+' Pacific').join(' &nbsp; / &nbsp; ')}</p><div class="panel tablewrap"><table><thead><tr><th>Player</th><th>Signed-up classes · select playable specs</th></tr></thead><tbody>${shortagePlayers().map(p=>`<tr><td class="playercell"><strong>${esc(p.name)}</strong>${tentativeRosterBadge(p)}${rosterFlagIcons(p)}<button class="removeplayer" aria-label="Remove ${esc(p.name)} from roster" onclick="removePlayer('${p.id}')">Remove</button><small class="availabilitylabel">Available runs</small>${runAvailabilityPicker(p)}</td><td>${quickSpecPicker(p)}</td></tr>`).join('')}</tbody></table></div>`}
function preset(v){if(v==='Balanced')template={Tank:[1,1],Healer:[1,2],Debuffer:[1,2],Buffer:[1,1]};if(v==='Progression')template={Tank:[2,2],Healer:[2,2],Debuffer:[2,2],Buffer:[1,1]};fellowshipSetup=emptyFellowshipSetup();ensureUnifiedRoles();optimize()}
