async function fetchRHEventData(){let lines=document.getElementById('rhevents').value.trim().split(/\s+/).filter(Boolean);if(!lines.length||lines.length>4)throw Error('Enter one to four event links or IDs.');let ids=lines.map(line=>{if(/^\d{17,20}$/.test(line))return line;let url=new URL(line);if(!['raid-helper.dev','www.raid-helper.dev','raid-helper.xyz','www.raid-helper.xyz','discord.com','www.discord.com'].includes(url.hostname))throw Error('Use a Raid-Helper event link, Discord message link, or event ID.');let matches=url.pathname.match(/\d{17,20}/g);if(!matches?.length)throw Error('No event ID found in '+line);return matches.at(-1)});if(new Set(ids).size!==ids.length)throw Error('The same event was entered more than once.');let events=[];for(let id of ids){let response=await fetch('https://raid-helper.xyz/api/v4/events/'+id,{credentials:'omit',signal:AbortSignal.timeout(20000)});let data=await response.json();if(!response.ok||data.status==='failed')throw Error(data.reason||'Cannot load event '+id);events.push(data)}return events}
let rhEvents=[],rhMappings={},rhDraft={},rhPreview=null,rhIssues=[],singleMulti=true,assumeAvailable=false,rhApplyMode='replace',rhPendingFiles=null,sessionPendingFile=null;
function importView(){return `${typeof recoveryMarkup==='function'?recoveryMarkup():''}<section class="panel" style="margin-bottom:20px"><h2>Session import / export</h2><p class="muted">Import a saved session or export your current plan. Session JSON includes players, selected specs, preferences, availability, run settings, comp requirements, templates and generated teams.</p><label class="field"><span>Saved session JSON</span><input type="file" accept=".json,application/json" onchange="sessionPendingFile=this.files[0];document.getElementById('sessionerror').textContent=''"></label><p class="rosteractions"><button class="primary" onclick="loadSessionButton()">Import session JSON</button><button onclick="exportSession()">Export session JSON</button></p><p id="sessionerror" role="alert"></p></section><section class="panel"><h2>Raid-Helper signups</h2><p class="muted">Import event links to replace the roster, or append players and classes. Tentative signups participate normally, with confirmed substitute suggestions. Select specs and availability in Roster.</p><label class="field"><span>Event links or IDs · one per line, up to four</span><textarea id="rhevents" placeholder="https://raid-helper.dev/raid/123456789012345678"></textarea></label><p><button class="primary" id="rhload" onclick="startRH('replace')">Import</button> <button id="rhappend" onclick="startRH('append')">Append</button></p><p id="rherror" role="alert"></p><p id="rhfetchstatus" role="status"></p><div id="rhpreview">${rhPreviewMarkup()}</div></section>`}
async function loadSessionButton(){if(!sessionPendingFile){document.getElementById('sessionerror').textContent='Choose a session JSON file first.';return}await restoreSessionFile(sessionPendingFile)}
async function gatherRHEvents(){if(!document.getElementById('rhevents').value.trim())throw Error('Enter a Raid-Helper event link or ID.');return await fetchRHEventData()}
async function startRH(mode){let loadBtn=document.getElementById('rhload'),appendBtn=document.getElementById('rhappend'),status=document.getElementById('rhfetchstatus'),error=document.getElementById('rherror');try{if(error)error.textContent='';if(status)status.textContent='Loading event signups…';if(loadBtn)loadBtn.disabled=true;if(appendBtn)appendBtn.disabled=true;rhApplyMode=mode;let events=await gatherRHEvents();setRHEvents(events);applyRH();toast((mode==='append'?'Appended':'Imported')+' '+events.length+' Raid-Helper event'+(events.length===1?'':'s')+'.')}catch(e){let err=document.getElementById('rherror')||error;if(err)err.textContent=e.message;else toast(e.message);let st=document.getElementById('rhfetchstatus');if(st)st.textContent=''}finally{let lb=document.getElementById('rhload')||loadBtn,ab=document.getElementById('rhappend')||appendBtn;if(lb)lb.disabled=false;if(ab)ab.disabled=false}}
function setRHEvents(events){if(!events.length||events.length>4)throw Error('Import between one and four events.');if(events.some(e=>!Array.isArray(e.signUps||e.signups)))throw Error('Each event must contain a signUps or signups array.');rhEvents=events;singleMulti=events.length===1;assumeAvailable=true;rhMappings={};rhDraft={};buildRHPreview()}
function rhClassLabels(row){return [row.cClassName,row.className,row.class,row.cName].filter(v=>v!=null&&String(v).trim()!=='').map(v=>String(v))}
function rhSpecLabels(row){let raw=[row.cSpecName,row.specName??row.spec,row.cSpec2Name,row.spec2Name??row.spec2,row.cSpec3Name,row.spec3Name??row.spec3];let seen=new Set,out=[];for(let s of raw){let t=String(s??'').trim();if(!t)continue;let key=t.toLowerCase();if(seen.has(key))continue;seen.add(key);out.push(t)}return out}
function rhKey(row){return [...rhClassLabels(row).slice(0,1),...rhSpecLabels(row)].join(' | ')||String(row.className??row.cClassName??row.class??'')}
function canonicalClass(label){let normalized=String(label).toLowerCase().replace(/[^a-z]/g,'');if(!normalized)return;normalized=({minstral:'minstrel',rk:'runekeeper',runekeeper:'runekeeper',lm:'loremaster',loremaster:'loremaster',guard:'guardian',guardian2:'guardian',hunter1:'hunter'}[normalized])||normalized;return Object.keys(classes).find(c=>normalized===c.toLowerCase().replace(/[^a-z]/g,''))||Object.keys(classes).sort((a,b)=>b.length-a.length).find(c=>normalized.includes(c.toLowerCase().replace(/[^a-z]/g,'')))}
function rhColorFromLabel(label){let text=String(label).toLowerCase().replace(/[_-]/g,' ');let prefix=String(label).toLowerCase().match(/^(blue|red|yellow)(?=[^a-z]|$)/);if(prefix)return prefix[1][0].toUpperCase()+prefix[1].slice(1);return ['Blue','Red','Yellow'].find(c=>new RegExp('(^|[^a-z])'+c.toLowerCase()+'([^a-z]|$)').test(text))}
function detectRH(row){let specs=rhSpecLabels(row),classMatch=null,classLabel='';for(let label of rhClassLabels(row)){classMatch=canonicalClass(label);if(classMatch){classLabel=label;break}}if(!classMatch){for(let spec of specs){classMatch=canonicalClass(spec.replace(/^(blue|red|yellow)[_-]?/i,''));if(classMatch){classLabel=spec;break}}}if(!classMatch)return [];let result=[];for(let spec of specs){let color=rhColorFromLabel(classLabel+' '+spec)||rhColorFromLabel(spec);let found=color&&opts.find(o=>o.c===classMatch&&o.spec===color);if(found&&!result.some(o=>o.c===found.c&&o.spec===found.spec))result.push(found);if(spec&&!found)return []}return result.length?result:opts.filter(o=>o.c===classMatch).map(o=>({...o,flexible:true}))}
