function buildDiscordMessages(){let messages=[];for(let t of teams){let header=`**${discordSafe(t.label,100)} · ${time(t.time)} Pacific**\n${t.members.length}/${size} players${t.valid?'':' · Incomplete team'}`;let lines=[];for(let role of roleOrder){let members=t.members.filter(p=>p.role===role);if(!members.length)continue;lines.push(`\n**${role}**`);for(let p of members){let color={Blue:'🟦',Red:'🟥',Yellow:'🟨'}[p.spec]||'⬜';lines.push(`${discordClass(p.c)} ${color} **${discordSafe(p.name)}** — ${p.spec} ${p.c}`)}}if(t.repeatCount)lines.push(`\nSame-player/class repeats: ${t.repeatCount}.`);if(t.shortages?.length)lines.push('\nMissing: '+t.shortages.map(r=>r.count+' '+r.role).join(', '));let text=header;let part=1;for(let line of lines){if((text+'\n'+line).length>1900){messages.push({label:t.label+' · part '+part,text});part++;text=header+'\n*(continued)*'}text+='\n'+line}messages.push({label:t.label+(part>1?' · part '+part:''),text})}return messages}
